import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class CsvTableStoreTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void save(Path file, String[] header, List<String[]> rows) {
        try {
            CsvTableStore.save(file, header, rows);
        } catch (Exception e) {
            System.out.println("FAIL  save threw " + e.getClass().getSimpleName());
            failures++;
        }
    }

    static String header(Path file) {
        try {
            String[] h = CsvTableStore.loadHeader(file);
            return h == null ? "null" : java.util.Arrays.toString(h);
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    static List<String[]> rows(Path file) {
        try {
            List<String[]> r = CsvTableStore.loadRows(file);
            return r == null ? new ArrayList<>() : r;
        } catch (Exception e) {
            System.out.println("FAIL  loadRows threw " + e.getClass().getSimpleName());
            failures++;
            return new ArrayList<>();
        }
    }

    static String row(List<String[]> rows, int index) {
        if (index >= rows.size()) {
            return "<missing>";
        }
        return java.util.Arrays.toString(rows.get(index));
    }

    public static void main(String[] args) throws Exception {
        Path file = Files.createTempFile("csvtable", ".csv");
        Path headerOnly = Files.createTempFile("csvheader", ".csv");
        try {
            String[] head = {"name", "qty", "shelf"};
            List<String[]> data = new ArrayList<>();
            data.add(new String[] {"bolt", "12", "A"});
            data.add(new String[] {"washer", "7", "B"});
            data.add(new String[] {"hex key", "0", "C"});
            save(file, head, data);

            String text = Files.readString(file, StandardCharsets.UTF_8)
                    .replace(System.lineSeparator(), "\n");
            check("file text", "name,qty,shelf\nbolt,12,A\nwasher,7,B\nhex key,0,C\n", text);

            check("header round trip", "[name, qty, shelf]", header(file));
            List<String[]> back = rows(file);
            check("row count", 3, back.size());
            check("first row", "[bolt, 12, A]", row(back, 0));
            check("last row", "[hex key, 0, C]", row(back, 2));

            save(headerOnly, new String[] {"only"}, new ArrayList<String[]>());
            check("header only file header", "[only]", header(headerOnly));
            check("header only file rows", 0, rows(headerOnly).size());

            List<String[]> replacement = new ArrayList<>();
            replacement.add(new String[] {"nut", "1", "Z"});
            save(file, head, replacement);
            check("save overwrites", 1, rows(file).size());
        } finally {
            Files.deleteIfExists(file);
            Files.deleteIfExists(headerOnly);
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

