import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class CsvTableStore {

    public static void save(Path file, String[] header, List<String[]> rows) throws IOException {
        List<String> lines = new ArrayList<>();
        lines.add(String.join(",", header));
        for (String[] row : rows) {
            lines.add(String.join(",", row));
        }
        Files.write(file, lines, StandardCharsets.UTF_8);
    }

    public static String[] loadHeader(Path file) throws IOException {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        if (lines.isEmpty()) {
            return new String[0];
        }
        return lines.get(0).split(",", -1);
    }

    public static List<String[]> loadRows(Path file) throws IOException {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        List<String[]> rows = new ArrayList<>();
        for (int i = 1; i < lines.size(); i++) {
            rows.add(lines.get(i).split(",", -1));
        }
        return rows;
    }
}
